pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address to, uint256 amount) public {
        vm.assume(to != address(0));
        c.mintToken(address(this), amount);
        vm.assume(c.balanceOf(address(this)) >= amount);
        vm.assume(!c.frozenAccount(address(this)) && !c.frozenAccount(to));

        bool success;
        success = c.transfer(to, amount);
        assertTrue(success);
    }
}
